**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <map>
#include <iomanip>
using namespace std;

int main() {
    ifstream plik("rekordy.txt");
    string nazwisko, kat;
    int wartosc;

    map<string, int> ile, suma, maxW;

    while (plik >> nazwisko >> kat >> wartosc) {
        ile[kat]++;
        suma[kat] += wartosc;
        if (ile[kat] == 1 || wartosc > maxW[kat])
            maxW[kat] = wartosc;
    }

    cout << fixed << setprecision(2);
    cout << "a) Statystyki wg kategorii:" << endl;
    string bestKat;
    double bestSr = 0;
    for (auto &p : ile) {
        string k = p.first;
        double sr = (double)suma[k] / ile[k];
        cout << "   " << k << ": liczba=" << ile[k]
             << ", suma=" << suma[k]
             << ", srednia=" << sr
             << ", max=" << maxW[k] << endl;
        if (sr > bestSr) {
            bestSr = sr;
            bestKat = k;
        }
    }
    cout << "b) Najwyzsza srednia: " << bestKat << " (" << bestSr << ")" << endl;
    return 0;
}
```

**Wyjasnienie**: Trzy mapy przechowuja statystyki per kategoria: ilosc, sume i maksimum. Po wczytaniu iterujemy po mapach, obliczamy srednie i szukamy kategorii z najwyzsza srednia.

Weryfikacja:
- A: Kowalski 150, Wisniewski 300, Kaminski 120, Kozlowski 210
  ile=4, suma=150+300+120+210=780, sr=780/4=195.00, max=300
- B: Nowak 200, Zielinska 250, Wojcik 170
  ile=3, suma=200+250+170=620, sr=620/3=206.666...=206.67, max=250
- C: Lewandowski 180, Szymanski 350, Dabrowska 290
  ile=3, suma=180+350+290=820, sr=820/3=273.333...=273.33, max=350
- Najwyzsza srednia: C (273.33)
